import express from 'express';
import path from 'path';
import multer from 'multer';
import mammoth from 'mammoth';
import { GoogleGenAI } from '@google/genai';
import { createServer as createViteServer } from 'vite';

const upload = multer({ storage: multer.memoryStorage() });

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(express.json());

  // Health check endpoint
  app.get('/api/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  // AI Document Parsing Endpoint
  app.post('/api/parse-document', upload.single('file'), async (req, res) => {
    try {
      if (!req.file) {
        return res.status(400).json({ error: 'No file uploaded' });
      }

      let extractedText = '';

      // Check file type
      if (
        req.file.originalname.endsWith('.docx') ||
        req.file.originalname.endsWith('.doc') ||
        req.file.mimetype.includes('word')
      ) {
        const result = await mammoth.extractRawText({ buffer: req.file.buffer });
        extractedText = result.value;
      } else {
        extractedText = req.file.buffer.toString('utf-8');
      }

      const apiKey = process.env.GEMINI_API_KEY;
      if (!apiKey) {
        // Fallback to local parsing if Gemini API key not present
        return res.json({ 
          warning: 'GEMINI_API_KEY not configured, falling back',
          textSample: extractedText.substring(0, 500)
        });
      }

      const ai = new GoogleGenAI({ apiKey });

      const prompt = `
Bạn là chuyên gia bóc tách dữ liệu câu hỏi trắc nghiệm từ tài liệu.
Nhiệm vụ của bạn là đọc toàn bộ đoạn văn bản sau và trích xuất tất cả các câu hỏi trắc nghiệm thành danh sách định dạng JSON chuẩn. Không được bỏ sót hay giới hạn bất kỳ câu hỏi nào.

Mỗi câu hỏi phải chứa các thông tin sau:
- "content": Nội dung đầy đủ của câu hỏi
- "options": Mảng 4 đáp án dạng ["A. Nội dung A", "B. Nội dung B", "C. Nội dung C", "D. Nội dung D"]
- "correctAnswer": Ký tự đáp án đúng ("A", "B", "C", hoặc "D")
- "explanation": Lời giải thích ngắn gọn (nếu có trong đề hoặc tự tóm tắt ngắn)

Văn bản đầu vào:
---
${extractedText.substring(0, 300000)}
---

Chỉ trả về duy nhất chuỗi JSON có cấu trúc:
{
  "questions": [
    {
      "content": "...",
      "options": ["A. ...", "B. ...", "C. ...", "D. ..."],
      "correctAnswer": "C",
      "explanation": "..."
    }
  ]
}
`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          responseMimeType: 'application/json',
        },
      });

      const responseText = response.text || '{}';
      const parsedData = JSON.parse(responseText);

      return res.json(parsedData);
    } catch (err: any) {
      console.error('Error parsing document with Gemini:', err);
      return res.status(500).json({ 
        error: 'Failed to process document', 
        details: err?.message || String(err) 
      });
    }
  });

  // Vite middleware setup for local development / static file serving
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else if (!process.env.VERCEL) {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  if (!process.env.VERCEL) {
    app.listen(PORT, '0.0.0.0', () => {
      console.log(`Server running on http://0.0.0.0:${PORT}`);
    });
  }

  return app;
}

const appPromise = startServer();
export default appPromise;

